begin;
create temp table ap as select user_id u,partner_user_id partner,gen_random_uuid() a,gen_random_uuid() b,gen_random_uuid() t,gen_random_uuid() pending,gen_random_uuid() mortgage from partner_links where status='active' limit 1;
grant select on ap to authenticated;
insert into accounts(id,user_id,name,type,currency) select a,u,'Accounting fixture','checking','USD' from ap union all select b,partner,'Other fixture','checking','USD' from ap;
insert into transactions(id,user_id,account_id,name,date,amount,category,needs_review,pending) select t,u,a,'Prepaid fixture',date '1901-01-01',1200,'Insurance',true,false from ap union all select pending,u,a,'Pending fixture',date '1901-01-01',100,'Insurance',true,true from ap union all select mortgage,u,a,'Mortgage fixture',date '1901-01-01',1000,'Other',true,false from ap;
set local role authenticated;
do $$ declare f record;p jsonb;pid uuid;loanid uuid;lp jsonb;changed timestamptz;blocked boolean;begin select * into f from ap;if f.u is null then raise exception 'Fixture owner missing';end if;perform set_config('request.jwt.claim.sub',f.u::text,true);perform set_config('request.jwt.claim.role','authenticated',true);
lp:=jsonb_build_object('account_id',f.a,'name','Escrow fixture','kind','loan','category','Fees & Interest','total_amount',10000,'start_date','1901-01-01','end_date','1901-12-31','opening_escrow',400,'escrow_charges',jsonb_build_array(jsonb_build_object('date','1901-02-01','amount',150,'category','Taxes')),'payments',jsonb_build_array(jsonb_build_object('transaction_id',f.mortgage,'interest',100,'escrow',200)));loanid:=finance_save_accounting_plan(lp);if (select opening_escrow from finance_accounting_plans where id=loanid)<>400 then raise exception 'Escrow not saved';end if;select updated_at into changed from finance_accounting_plans where id=loanid;blocked:=false;begin perform finance_save_accounting_plan(lp||jsonb_build_object('id',loanid,'payments',jsonb_build_array(jsonb_build_object('transaction_id',f.mortgage,'interest',100,'escrow',1000))),changed);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Impossible mortgage split accepted';end if;
p:=jsonb_build_object('account_id',f.a,'name','Annual coverage fixture','kind','service','category','Insurance','total_amount',1200,'start_date','1901-02-01','end_date','1902-01-31','payments',jsonb_build_array(jsonb_build_object('transaction_id',f.t,'interest',0)));
pid:=finance_save_accounting_plan(p);select updated_at into changed from finance_accounting_plans where id=pid;
if (select needs_review from transactions where id=f.t) then raise exception 'Payment not marked reviewed';end if;
blocked:=false;begin perform finance_save_accounting_plan(p);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Duplicate assignment accepted';end if;
blocked:=false;begin perform finance_save_accounting_plan(jsonb_set(p,'{account_id}',to_jsonb(f.b)));exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Foreign account accepted';end if;
blocked:=false;begin perform finance_save_accounting_plan(jsonb_set(p,'{payments}',jsonb_build_array(jsonb_build_object('transaction_id',f.pending,'interest',0))));exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Pending payment accepted';end if;
p:=p||jsonb_build_object('id',pid,'name','Corrected fixture');perform finance_save_accounting_plan(p,changed);
blocked:=false;begin perform finance_save_accounting_plan(p,changed);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Stale plan accepted';end if;
if not exists(select 1 from finance_accounting_plan_audit where owner_id=f.u and payload->>'id'=pid::text) then raise exception 'Revision not retained';end if;
select updated_at into changed from finance_accounting_plans where id=pid;perform finance_save_accounting_plan(p||'{"is_void":true}'::jsonb,changed);if not (select is_void from finance_accounting_plans where id=pid) then raise exception 'Void failed';end if;perform finance_save_accounting_plan(p-'id');
perform set_config('request.jwt.claim.sub',f.partner::text,true);if exists(select 1 from finance_accounting_plans where id=pid) then raise exception 'Unshared plan exposed';end if;
blocked:=false;begin perform finance_save_accounting_plan(p,changed);exception when raise_exception then blocked:=true;end;if not blocked then raise exception 'Foreign plan edited';end if;
end $$;
reset role;rollback;
select 'PASS: earlier prepayments allowed; duplicate/pending/foreign assignments and stale edits blocked; private audit and owner isolation verified; fixtures rolled back.' as result;
